/// <reference types="astro/client" />

declare const __LAST_TENDED__: { date: string; hash: string };

// Bindings and [vars] are typed by `wrangler types` (worker-configuration.d.ts, generated by
// `npm run typecheck`). Secrets are not in wrangler.toml, so declare them here.
declare namespace Cloudflare {
  interface Env {
    GH_PROFILE_TOKEN?: string;
    RESEND_API_KEY?: string;
  }
}

declare namespace App {
  interface Locals {
    adminEmail?: string;
  }
}
